import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/OFF.BrU7kQE-.js";import{_ as a,a as r,b as s}from"./chunks/Diabox3.B9uDiRm7.js";import{_ as c,o as n,c as l,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"Follower Nightscout","description":"","frontmatter":{"source_hash":"247aedba5a","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/install/nightscoutfollower.md","filePath":"it/install/nightscoutfollower.md"}'),d={name:"it/install/nightscoutfollower.md"};function m(u,i,h,g,f,b){return n(),l("div",null,[...i[0]||(i[0]=[p('<div class="warning custom-block"><p class="custom-block-title">Certificati di Android obsoleti</p><p>Potresti non riuscire a usare questa funzione sui telefoni con versioni precedenti ad Android 9, se si basano su certificati scaduti (<a href="https://community.letsencrypt.org/t/support-for-android-7-and-older-from-oct-2024/216446" target="_blank" rel="noreferrer">esempio</a>).<br> Non c&#39;è alcuna soluzione.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Nightscout Follower</p></div><h3 id="nightscout" tabindex="-1">Nightscout <a class="header-anchor" href="#nightscout" aria-label="Permalink to &quot;Nightscout {#nightscout}&quot;">​</a></h3><p>Per usare xDrip con i dati provenienti dal tuo sito <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a>, devi solo inserire l&#39;URL del sito.</p><div class="admonition xdripitem"><p class="admonition-title">URL Nightscout Follow</p><p> Indirizzo Web per follow</p></div><p>Con un classico Nightscout fai-da-te, l&#39;URL sarà di questo tipo: <code>https://sitename.yourprovider.com</code><br> Non aggiungere <code>/api/v1</code><br> Assicurati di usare <code>https</code> e non <code>http</code></p><p>Se usi un servizio in hosting, contatta il fornitore per maggiori informazioni.</p><p>Se il tuo sito Nightscout è <a href="https://nightscout.github.io/nightscout/security/" target="_blank" rel="noreferrer">protetto</a>, devi aggiungere l&#39;API_SECRET o il token.</p><p><code>https://API_SECRET@sitename.yourprovider.com</code></p><p><code>https://access_token@sitename.yourprovider.com</code></p><div class="admonition xdripitem"><p class="admonition-title">Scarica trattamenti</p></div><p>Puoi anche scaricare da Nightscout i trattamenti compatibili (glicemia, calibrazioni, trattamenti, note).</p><div class="admonition xdripitem"><p class="admonition-title">Scarica trattamenti <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Scarica anche i trattamenti da Nightscout come follower</p></div><p>Se vuoi evitare il rischio di dati duplicati (importante per AAPS), puoi impedire a xDrip di scaricare i dati che ha caricato lui stesso su Nightscout.</p><div class="admonition xdripitem"><p class="admonition-title">Ignora gli elementi provenienti da xDrip <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Non scaricare gli elementi caricati da xDrip</p></div><p>Se in xDrip noti ritardi importanti, puoi impostare un ritardo fisso per risincronizzarlo con Nightscout. Lascia il valore predefinito.</p><div class="admonition xdripitem"><p class="admonition-title">Ritardo Nightscout Follower</p><p> 0&gt;</p></div><div class="info custom-block"><p class="custom-block-title">Nota</p><p>xDrip recupera da Nightscout i dati mancanti in modo limitato (24 ore).</p></div><p>Se il tuo sito Nightscout riporta lo stato dei dispositivi (batteria dell&#39;uploader, batteria del microinfusore), xDrip lo mostrerà in Stato del sistema.</p><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Anche gli emulatori locali di Nightscout come <a href="https://github.com/j-kaltes/Juggluco" target="_blank" rel="noreferrer">Juggluco</a> sono supportati come sorgente follower.</p></div><br><h3 id="diabox" tabindex="-1">Diabox <a class="header-anchor" href="#diabox" aria-label="Permalink to &quot;Diabox {#diabox}&quot;">​</a></h3><p>Puoi ricevere i dati da <a href="https://sirius.thetaphi.de/diabox/" target="_blank" rel="noreferrer">Diabox</a> attivando la trasmissione http nell&#39;app e impostando xDrip come follower locale.</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>Non puoi usare questa funzione se xDrip esegue un <a href="./../use/interapp.html#web-service">servizio web</a>.</p></div><img src="'+a+'" style="zoom:75%;"><img src="'+r+'" style="zoom:75%;"><p>Fatto questo, imposta xDrip come Nightscout follower (vedi sopra) con l&#39;indirizzo:</p><p><code>http://localhost:17580</code></p><img src="'+s+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.03" target="_blank" rel="noreferrer"><em>Ultima modifica 6/7/2026</em></a></p>',31)])])}const w=c(d,[["render",m]]);export{z as __pageData,w as default};
